import parse from 'html-react-parser';
import fs from "node:fs";
import path from "node:path";

function readAndTransformStaticHtml() {
  const htmlPath = path.join(process.cwd(), "index.html");
  const raw = fs.readFileSync(htmlPath, "utf8");

  const bodyMatch = raw.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  let body = bodyMatch?.[1] ?? "";

  // Prevent the legacy page from re-loading external JS bundles we've already moved to `app/layout.tsx`.
  // Keep inline scripts (e.g. the footer year script), but remove script tags with `src=`.
  body = body.replace(
    /<script\b[^>]*\bsrc=["'][^"']+["'][^>]*>[\s\S]*?<\/script>/gi,
    ""
  );

  // Make asset paths and internal links work with Next's exported routes.
  body = body
    .replace(/href="index\.html"/g, 'href="/"')
    .replace(/href="contact\.html"/g, 'href="/contact"')
    .replace(/href="portfolio\.html"/g, 'href="/portfolio"')
    .replace(/href="resume\.pdf"/g, 'href="/resume.pdf"')
    .replace(/src="img\//g, 'src="/img/')
    .replace(/src="fonts\//g, 'src="/fonts/')
    .replace(/src="css\//g, 'src="/css/')
    .replace(/src="js\//g, 'src="/js/')
    .replace(/src="vendors\//g, 'src="/vendors/');

  const year = String(new Date().getUTCFullYear());
  body = body.replace(
    /<script>\s*document\.write\(new Date\(\)\.getFullYear\(\)\);\s*<\/script>/gi,
    year
  );

  return body;
}

export default function HomePage() {
  const html = readAndTransformStaticHtml();
  const normalizedHtml = html.replace(/\r\n/g, '\n');
  return <main>{parse(normalizedHtml)}</main>;
}

